  const worker=new Worker('/build/'+workerBundle,{type:'module'}),rows=[];
  try{for(const c of cases){
   const result=await new Promise((resolve,reject)=>{worker.onmessage=e=>resolve(e.data);worker.onerror=e=>reject(Error(e.message));worker.postMessage({model:c.model,lod:c.lod,infected:c.infected,cpuRate:1});});
