 const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',e=>{if(e.type()==='error')errors.push(e.text());});
 await page.addInitScript(backend=>{window.__name=fn=>fn;if(backend==='webgl2')Object.defineProperty(navigator,'gpu',{value:undefined});},backend);
 await page.goto(`http://127.0.0.1:4901/?test=poses&testApi=1&scenelab=1&profile=1&preload=0&dpr=1&quality=high&audio=muted&seed=1${backend==='webgl2'?'&renderer=webgl':''}`);
 await page.waitForFunction(()=>!!window.__SS__&&!!window.__SCENE__);
 const result=await page.evaluate(async()=>{
  const a=window.__SS__;await a.ready;a.pause();await a.loadLevel('L10',{seed:1,progression:'L10-default'});a.pause();
  const g=window.__SCENE__.game,c=g.view.crowd;
  const definitions=[...c.definitions].filter(([key,d])=>/^inf\.(?:mega-)?alpha(?:[.-]|$)/.test(d.asset));
  const records=[];
  for(const [key,def]of definitions){
   // Deliberately ask for the far tier first: its retained corpse must still bind LOD0.
   await c.requestBatch(def,'lod2');await c.requestBatch(def,'lod1');
   const first=c.batches.get(`${key}:lod0`),atlas0=first.mesh.userData.preRenderTextures[1];
   if(!atlas0)throw Error('Missing LOD0 atlas '+key);
   for(const lod of ['lod2','lod1','lod0']){
    const b=c.batches.get(`${key}:${lod}`),s=[...c.sharedSkinMaterials.values()].find(v=>v.material===b.mesh.material),want=b.mesh.userData.preRenderTextures[1];
    if(!s)throw Error('Unshared Alpha material '+key+':'+lod);
    b.mesh.onBeforeRender();
    if(s.pose.value!==b.texture||s.atlas.value!==want)throw Error('Wrong living atlas/pose '+key+':'+lod);
    records.push({key,lod,material:b.mesh.material.uuid,atlas:want.uuid,pose:b.texture.uuid,livingBindingCorrect:true});
   }
   const shared=[...c.sharedSkinMaterials.values()].find(v=>v.material===first.mesh.material);
   const pages=c.staticCorpses.children.filter(p=>p.name.startsWith(`corpses:${key}:`));
   if(!pages.length)throw Error('Missing Alpha corpse pages '+key);
   for(const page of pages){
    if(page.userData.preRenderTextures[0]!==atlas0)throw Error('Corpse source is not LOD0 atlas '+key);
    page.onBeforeRender();if(shared.atlas.value!==atlas0)throw Error('Wrong frozen atlas '+key);
    records.push({key,page:page.name,atlas:atlas0.uuid,corpseBindingCorrect:true});
   }
  }
  await a.step(2);await a.screenshotReady();
  const gl=g.view.renderer.backend.gl;
  return {backend:g.view.renderer.selectedBackend,contextVersion:gl?.getParameter(gl.VERSION),models:definitions.length,livingMaterials:new Set(records.filter(r=>r.lod).map(r=>r.material)).size,records};
 });
 await page.screenshot({path:`test-results/perf10/alpha-bindings-${backend}.png`});
 assert.equal(result.backend,backend==='webgl2'?'webgl':'webgpu');if(backend==='webgl2')assert.match(result.contextVersion,/WebGL 2/);assert(result.models>=4);assert.deepEqual(errors,[]);
 rows.push({...result,errors});await context.close();
 console.log(JSON.stringify({backend,models:result.models,livingChecks:result.records.filter(r=>r.lod).length,corpseChecks:result.records.filter(r=>r.page).length,livingMaterials:result.livingMaterials,errors}));
}}finally{await browser.close();}
fs.writeFileSync('test-results/perf10/alpha-bindings.json',JSON.stringify({at:new Date().toISOString(),rows},null,2));

