import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import { gunzipSync } from 'node:zlib';
import { build } from 'esbuild';
import { BufferAttribute, MeshLambertNodeMaterial } from 'three/webgpu';
import { decodeCivilianBake } from '../../src/assets/civilianBakeData.ts';
import { packCrowdParts } from '../../src/assets/crowd.ts';
import { framesPerClip, civilianClips, infectedClips } from '../../src/render/characters/bakeInfected.ts';
const root='test-results/perf10',sha=b=>crypto.createHash('sha256').update(b).digest('hex'),modules={},identities={};
for(const stem of ['StaticCorpses','deathPose','skinnedCrowd']){
 identities[stem]={};modules[stem]={};
 for(const label of ['before','after']){
  const file=label==='before'?`${root}/${stem}.before.txt`:`src/render/characters/${stem}.ts`,source=fs.readFileSync(file,'utf8'),outfile=path.resolve(`${root}/${stem}-${label}.mjs`);
  identities[stem][label]=sha(source);
  const plugins=label==='before'?[{name:'original-skin-helper',setup(ctx){ctx.onResolve({filter:/^\.\/skinnedCrowd$/},()=>({path:'original-skin',namespace:'original'}));ctx.onLoad({filter:/.*/,namespace:'original'},()=>({contents:fs.readFileSync(`${root}/skinnedCrowd.before.txt`,'utf8'),loader:'ts',resolveDir:path.resolve('src/render/characters')}));}}]:[];
  await build({stdin:{contents:source,resolveDir:path.resolve('src/render/characters'),sourcefile:stem+'.ts',loader:'ts'},outfile,bundle:true,format:'esm',platform:'node',packages:'external',plugins,define:{__QA_HOOKS__:'true',__ASSET_VERSIONS__:'{}','import.meta.env.DEV':'false'}});
  modules[stem][label]=await import(outfile);
 }
}
const manifest=JSON.parse(fs.readFileSync('src/assets/civilianBakes.json','utf8'));
const models=['npc.civilian-man-a','npc.civilian-woman-b','npc.civilian-elderly','npc.national-guard','inf.common-worker','inf.cashier','inf.alpha','inf.delivery-driver'];
const material=new MeshLambertNodeMaterial(),cases=[],inputs=[],poseCases=[];let serial=0,helperVertices=0;
const bytesOf=a=>Buffer.from(a.buffer,a.byteOffset,a.byteLength);
function digest(g){
 assert(g.getAttribute('position').count>0);for(const a of Object.values(g.attributes))assert(a.array.every(Number.isFinite),'finite geometry');assert(Number.isFinite(g.boundingSphere.radius));
 const attributes=Object.fromEntries(Object.entries(g.attributes).map(([name,a])=>[name,{size:a.itemSize,normalized:a.normalized,type:a.array.constructor.name,bytes:sha(bytesOf(a.array))}]));
 return {attributes,index:g.index?{type:g.index.array.constructor.name,bytes:sha(bytesOf(g.index.array))}:null,sphere:{center:g.boundingSphere.center.toArray(),radius:g.boundingSphere.radius}};
}
try{
 for(const model of models)for(const lod of ['lod0','lod1','lod2']){
  const key=`${model}:${lod}${model.startsWith('inf.')?':infected':''}`,url=manifest[key];assert(url,`missing ${key}`);
  const bytes=fs.readFileSync(`public${url}`),raw=gunzipSync(bytes),decoded={},poseTime={},poseResult={};
  inputs.push({key,url,sha256:sha(bytes)});
  for(const label of poseCases.length%2?['after','before']:['before','after']){
   const bake=decodeCivilianBake(raw.buffer.slice(raw.byteOffset,raw.byteOffset+raw.byteLength));packCrowdParts(bake.geometry);decoded[label]=bake;
   const start=performance.now(),repaired=modules.deathPose[label].repairDeathPoses(bake.clip,bake.geometry,{prone:model==='inf.alpha'});poseTime[label]=performance.now()-start;
   poseResult[label]={repaired,matrices:sha(bytesOf(bake.clip.matrices)),reach:modules.deathPose[label].deathReach.get(bake.clip)};
  }
  assert.deepEqual(poseResult.after,poseResult.before,`${key} repaired clip matrices`);assert(poseResult.after.repaired);
  poseCases.push({key,identical:true,ms:poseTime,clipSha256:poseResult.after.matrices,reach:poseResult.after.reach});decoded.before.geometry.dispose();
  const bake=decoded.after,clips=model.startsWith('inf.')?infectedClips:civilianClips;
  for(const death of ['death-back','death-side','death-crumple']){
   const frame=clips.indexOf(death)*framesPerClip+framesPerClip-1,P=bake.clip.parts.length,offset=frame*P*16;assert(frame>=0&&(frame+1)*P*16<=bake.clip.matrices.length);
   const pose=new Float32Array(P*16),a=new Float32Array(16),b=new Float32Array(16),row=new Float32Array(16),parts=bake.geometry.getAttribute('_parts'),skin=bake.geometry.getAttribute('_skin');
   modules.skinnedCrowd.after.premultiplyRow(bake.clip.matrices,pose,bake.clip.binds,offset,P,0);
   for(let i=0;i<parts.count;i+=Math.max(1,Math.floor(parts.count/256))){
    modules.skinnedCrowd.before.skinnedVertexMatrix(bake.clip,offset,parts,skin,i,a,pose);
    modules.skinnedCrowd.after.skinnedVertexMatrix(bake.clip,offset,parts,skin,i,b,pose);
    modules.skinnedCrowd.after.skinnedVertexMatrix(bake.clip,offset,parts,skin,i,row,pose,1);
    assert(bytesOf(a).equals(bytesOf(b)),`${key} full skin matrix`);
    for(let j=0;j<16;j++)assert(Object.is(row[j],j%4===1?a[j]:0),`${key} vertical row`);helperVertices++;
   }
   for(const hair of [false,true])for(const mask of [[],['armL','foreArmL']]){
    const padded=serial%2===0,source=bake.geometry.clone();
    if(padded){const n=source.getAttribute('normal'),data=new Float32Array(n.count*4);for(let i=0;i<n.count;i++){data[i*4]=n.getX(i);data[i*4+1]=n.getY(i);data[i*4+2]=n.getZ(i);}source.setAttribute('normal',new BufferAttribute(data,4));}
    const result={},time={};
    for(const label of serial++%2?['after','before']:['before','after']){
     const pool=new modules.StaticCorpses[label].StaticCorpses(),start=performance.now();
     try{const frozen=pool.frozenPose(source,material,bake.clip,frame,mask,hair);time[label]=performance.now()-start;result[label]=digest(frozen.geometry);}
     finally{pool.dispose();}
    }
    assert.deepEqual(result.after,result.before,`${key} ${death} hair=${hair} mask=${mask}`);
    cases.push({key,death,hair,mask,paddedNormal:padded,identical:true,ms:time,geometrySha256:sha(JSON.stringify(result.before))});source.dispose();
   }
  }
  bake.geometry.dispose();
 }
}finally{material.dispose();}
const sum=(list,side)=>list.reduce((n,r)=>n+r.ms[side],0),totals=Object.fromEntries(['before','after'].map(s=>[s,sum(cases,s)])),poseTotals=Object.fromEntries(['before','after'].map(s=>[s,sum(poseCases,s)]));
const receipt={at:new Date().toISOString(),sourceIdentities:identities,beforeSourceSha256:identities.StaticCorpses.before,afterSourceSha256:identities.StaticCorpses.after,cases:cases.length,bitIdenticalCases:cases.filter(r=>r.identical).length,poseCases:poseCases.length,bitIdenticalPoseCases:poseCases.filter(r=>r.identical).length,helperCases:poseCases.length*3,helperVertices,totalsMs:totals,speedup:totals.before/totals.after,poseTotalsMs:poseTotals,poseSpeedup:poseTotals.before/poseTotals.after,inputs,poseMeasurements:poseCases,measurements:cases};
fs.writeFileSync(`${root}/frozen-equivalence-${Date.now()}.json`,JSON.stringify(receipt,null,2));fs.writeFileSync(`${root}/frozen-equivalence.json`,JSON.stringify(receipt,null,2));console.log({cases:receipt.cases,bitIdentical:receipt.bitIdenticalCases,poseCases:receipt.poseCases,helperCases:poseCases.length*3,helperVertices,totalsMs:totals,speedup:receipt.speedup,poseTotalsMs:poseTotals,poseSpeedup:receipt.poseSpeedup});

