import json,pathlib,hashlib,datetime,subprocess,re,math,collections,gzip,platform
R=pathlib.Path('test-results/perf10');O=pathlib.Path('docs/reports/perf10');O.mkdir(parents=True,exist_ok=True)
def read(p):return json.loads(pathlib.Path(p).read_text())
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def put(n,x):(O/n).write_text(json.dumps(x,indent=2)+'\n')
def native(r,p):
 f=r.get('performance');d={k:r.get(k)for k in ['side','level','tier','backend','seconds','diagnostic','hardware','measuredAt','control','terminalInputWithheld','errors','failure','proof','nativeBeat']};d.update(rawSource=str(p),rawSha256=sha(p))
 if not f:return d
 d['performance']={k:f.get(k)for k in ['startedAt','tick','level','nonGameplayFrames','durationMs','endTick','frames','warFrames','chargeFrames','missionFrames','builds','frozenBakes','lateMeasures','maxMs','p95Ms']}
 d['events']=[{k:e[k]for k in ['type','at','tick','sourceId','targetId','attackId','actionId','name','defId','id']if k in e}for e in f.get('events',[])]
 d['samples']=[{k:s.get(k)for k in ['wallSeconds','scenario','loading','tick','backend','quality','player','alive','alphas','phase','objective','completed']}for s in r['samples']]
 d['inputFrames']=len(f.get('inputs',[]));d['inputSha256']=hashlib.sha256(json.dumps(f.get('inputs',[]),sort_keys=True,separators=(',',':')).encode()).hexdigest();return d
def natives(area):return [native(r,p)for p in sorted((R/area).glob('*/strips/webgpu/*.json'))for r in read(p)]
def loads(area):
 return [{k:r.get(k)for k in ['side','level','tier','backend','temperature','measuredAt','errors','ms','start','shown','done','stages','loadMeasures','quality','bundle','begin','contexts','adapter','glRenderer','diagnostic']}|dict(rawSource=str(p),rawSha256=sha(p),networkCount=len(r['network']),networkStatuses=dict(collections.Counter(str(v['status'])for v in r['network'])))for p in sorted((R/area).glob('*/loads/*.json'))for r in read(p)]
